with flattened_attrs as (select id, host, log_ts, level, latency_ms, payload_json, cast((status_code & 2) != 0 as int) as has_fault, coalesce(context['version'], 'unknown') as version_or_default, context['version'] as version, context['region'] as region, context['trace'] as trace from app_logs where log_ts >= '2023-11-21') select id, host, log_ts, level, latency_ms, payload_json, has_fault, version_or_default, version, region, trace, last_value(latency_ms) ignore nulls over (partition by level order by log_ts, id rows between unbounded preceding and current row) as last_known_latency_ms, sum(has_fault) over (partition by host order by has_fault, id rows between unbounded preceding and current row) as running_has_fault, row_number() over (order by has_fault, id) as seq_no from flattened_attrs;
